#include <Wire.h>

const int PIN_IN1 = 2;
const int PIN_IN2 = 3;

const uint8_t AS5600_ADDR = 0x36;
const uint8_t VL53L0X_ADDR = 0x29;

void setMotorSpeed(int speed) {
  speed = constrain(speed, -255, 255);
  if (speed > 0) {
    analogWrite(PIN_IN1, speed);
    analogWrite(PIN_IN2, 0);
  } else if (speed < 0) {
    analogWrite(PIN_IN1, 0);
    analogWrite(PIN_IN2, -speed);
  } else {
    analogWrite(PIN_IN1, 0);
    analogWrite(PIN_IN2, 0);
  }
}

uint16_t readAngle(TwoWire &bus) {
  bus.beginTransmission(AS5600_ADDR);
  bus.write(0x0C);
  bus.endTransmission(false);
  bus.requestFrom((int)AS5600_ADDR, 2);
  if (bus.available() >= 2) {
    uint16_t high = bus.read();
    uint16_t low = bus.read();
    return ((high & 0x0F) << 8) | low;
  }
  return 0;
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_IN1, OUTPUT);
  pinMode(PIN_IN2, OUTPUT);
  setMotorSpeed(0);

  Wire.begin();
  Wire.setClock(400000);

  Wire1.begin();
  Wire1.setClock(400000);
}

void loop() {
  uint16_t angle1 = readAngle(Wire);
  uint16_t angle2 = readAngle(Wire1);

  Serial.print("Pivot Angle: ");
  Serial.print(angle1);
  Serial.print(" | Elbow Angle: ");
  Serial.println(angle2);

  delay(10);
}

